 out=make_views_batch(x,'xillum',v,torch.Generator().manual_seed(42));m=torch.stack([o[:,24:,0,0] for o in out]);print('xillum',v,'counts',m.sum(-1).tolist(),'coverage',m.sum(0).unique().tolist(),'absent_zero',all((o[:,:24]*(1-o[:,24:])==0).all() for o in out),flush=True)
