for f,defs in [('scripts/train_bind.py',{'retr','near_dup'}),('scripts/screen_gs_lf.py',{'retr','siglip_fit'})]:
 tree=ast.parse((root/f).read_text());mod=ast.Module(body=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name in defs],type_ignores=[]);ns={'torch':torch,'np':np,'F':torch.nn.functional,'dev':'cpu'}
 if 'near_dup' in defs:
  t=np.load(W+'/targets_v2.npz');ns.update(Mt=torch.tensor([[1,0,1],[0,1,1]],dtype=torch.bool),Yt=torch.tensor([[5.,0.,.1],[0.,-4.,.2]]),a=type('Args',(),{'tau':.25})())
 exec(compile(mod,f,'exec'),ns);const=np.ones((100,4),dtype=np.float32);A=torch.tensor(const) if 'near_dup' in defs else const;print(f,'collapsed',ns['retr'](A,A),flush=True)
 if 'near_dup' in defs: print('near_dup different sets',ns['near_dup'](torch.arange(2)).tolist(),flush=True)
 else:
  fg,fl=ns['siglip_fit'](np.ones((10,3),np.float32),np.ones((10,3),np.float32),dim=2,steps=1)
  try:fg(np.ones((2,3),np.float32))
